function rankMovement<T extends {id:string}>(items:T[],previous:T[]|undefined) {
  const oldRanks=new Map((previous||[]).map((item,index)=>[item.id,index+1]));
  return new Map(items.map((item,index)=>[item.id,{previous:oldRanks.get(item.id),current:index+1}]));
}
const dailyMovements={news:rankMovement(daily.news,previousDaily?.news),projects:rankMovement(daily.projects,previousDaily?.projects),models:rankMovement(daily.trendingModels,previousDaily?.trendingModels)};
function movementBadge(movement:{previous:number|undefined,current:number}|undefined) {
  if(!movement) return "";
  if(!movement.previous) return `<span class="rank-movement new">新上榜</span>`;
  const delta=movement.previous-movement.current;
  if(delta>0) return `<span class="rank-movement up">↑ ${delta}</span>`;
  if(delta<0) return `<span class="rank-movement down">↓ ${Math.abs(delta)}</span>`;
  return `<span class="rank-movement flat">持平</span>`;
}

