function directoryFreshness(kind:"model"|"relay") {
  const checks=directory.checks.filter(item=>item.kind===kind);
  const responded=checks.filter(item=>item.state==="reachable"||item.state==="restricted").length;
  const missing=checks.filter(item=>item.state==="not_found").length;
  const limited=checks.filter(item=>item.state==="network_limited"||item.state==="temporary_error").length;
  return `<div class="freshness"><span><i class="live-dot"></i> 目录数据 ${esc(directoryDate)}</span><span>每日 06:15 更新</span><span>已响应 ${responded}</span><span>确认失效 ${missing}</span><span>环境或临时受限 ${limited}</span></div>`;
}
