function digestPage(snapshot:DailySnapshot,archive=false) {
  const prefix=archive?`/daily/${snapshot.date}/`:"";
  const currentCta=archive?`<section class="method-strip"><b>这是 ${esc(snapshot.date)} 的归档</b><p>今天的榜单已更新到 ${esc(daily.date)}，可查看最新 AI 新闻、热门项目和趋势模型。</p><a class="button primary" href="/daily/" data-track="archive-current">查看今天的 AI 热点 →</a></section>`:"";
  const movementNote=!archive&&previousDaily?`<section class="method-strip rank-explainer"><b>和 ${previousDaily.date} 相比</b><p><span class="rank-movement new">新上榜</span> 表示昨日榜中没有该条目；↑ / ↓ 为相对昨日的名次变化。同一榜单按各自公开信号计算，不跨榜比较。</p></section>`:"";
  const movements=!archive&&snapshot.date===daily.date?dailyMovements:undefined;
  return layout(`${snapshot.date} 每日 AI 热点`,`${snapshot.date} 的 10 条热门 AI 新闻、10 个热门 AI 开源项目和 10 个趋势模型。`,archive?`/daily/${snapshot.date}/`:"/daily/",`<section class="page-head daily-head"><span class="kicker">DAILY AI RADAR</span><h1>今天 AI 圈<br><em>值得看什么</em></h1><p>每天聚合 10 条 AI 新闻、10 个热门开源项目和 10 个趋势模型。排名来自公开热度信号，不是付费推荐。</p>${freshness(snapshot)}</section>${currentCta}${movementNote}${shareBar("每天 3 个 Top 10，转给不想刷信息流的人")}<section class="daily-columns"><a href="${prefix || "/news/"}${prefix?"#news":""}"><span>01</span><b>AI 热门新闻</b><small>HN 投票、评论与时间衰减 →</small></a><a href="${prefix || "/projects/"}${prefix?"#projects":""}"><span>02</span><b>AI 热门项目</b><small>GitHub Trending 与星标增速 →</small></a><a href="${prefix || "/trending-models/"}${prefix?"#models":""}"><span>03</span><b>趋势模型</b><small>Hugging Face 趋势榜 →</small></a></section><section id="news" class="ranking-section"><div class="section-title"><div><span class="kicker">TOP 10 NEWS</span><h2>AI 热门新闻</h2></div>${archive?"":`<a href="/news/">完整榜单与口径 →</a>`}</div><div class="rank-list">${snapshot.news.slice(0,archive?10:5).map((item,index)=>newsItem(item,index,movements?.news)).join("")}</div></section><section id="projects" class="ranking-section"><div class="section-title"><div><span class="kicker">TOP 10 PROJECTS</span><h2>AI 热门项目</h2></div>${archive?"":`<a href="/projects/">完整榜单与口径 →</a>`}</div><div class="rank-list">${snapshot.projects.slice(0,archive?10:5).map((item,index)=>projectItem(item,index,movements?.projects)).join("")}</div></section><section id="models" class="ranking-section"><div class="section-title"><div><span class="kicker">TRENDING MODELS</span><h2>趋势模型</h2></div>${archive?"":`<a href="/trending-models/">完整榜单与口径 →</a>`}</div><div class="rank-list">${snapshot.trendingModels.slice(0,archive?10:5).map((item,index)=>trendModelItem(item,index,movements?.models)).join("")}</div></section>${archive?"":`<section class="archive-block"><h2>每日归档</h2><p>保留过去 90 天快照，便于回看趋势变化。</p><div>${dailyHistory.map(x=>`<a href="/daily/${x.date}/">${x.date}</a>`).join("")}</div></section>`}`);
}

