function moneyNewsCard(item:AIMoneyNews,index:number){return `<article class="opportunity-card card" data-search="${esc(`${item.title} ${item.source} ${item.sourcePlatforms.join(" ")} ${item.signal}`.toLowerCase())}" data-signal="${esc(item.signal)}"><span class="opportunity-rank">${String(index+1).padStart(2,"0")}</span><div><div class="card-head"><span class="eyebrow">${esc(item.signal)} · ${esc(item.source)}</span><time datetime="${item.publishedAt}">${zhDate(item.publishedAt)}</time></div><h2>${ext(item.url,item.title,"","money-news")}</h2><div class="fusion-scores"><b>融合 ${item.fusionScore}</b><span>站内热度 ${item.engagementScore}</span><span>时效 ${item.freshnessScore}</span><span>跨源 ${item.coverageScore}</span></div><div class="card-actions">${item.evidence.map(source=>ext(source.url,source.platform,"","money-source")).join("")}${saveButton(`money:${item.id}`,item.title,item.url,`${item.signal} · AI 创收资讯`)}</div></div></article>`}
function skillCard(item:TrendingSkill,index:number,movement?:Map<string,{previous:number|undefined,current:number}>){return `<article class="skill-card card" data-search="${esc(`${item.name} ${item.source}`.toLowerCase())}"><span class="opportunity-rank">${String(index+1).padStart(2,"0")}</span><div><div class="card-head"><span class="eyebrow">${esc(item.source)}</span>${movementBadge(movement?.get(item.id))}</div><h2>${ext(item.url,item.name,"","skill")}</h2><p><b>${compactNumber(item.installs)}</b> 安装趋势 · ${compactNumber(item.githubStars)} Star · ${compactNumber(item.githubForks)} Fork</p><div class="fusion-scores"><b>融合 ${item.fusionScore}</b><span>安装 ${item.installScore}</span><span>仓库 ${item.repositoryScore}</span><span>活跃 ${item.freshnessScore}</span></div><div class="card-actions">${item.installUrl?ext(item.installUrl,"查看 GitHub 仓库","","skill-source"):""}${saveButton(`skill:${item.id}`,item.name,item.url,`Agent Skill · ${item.source}`)}</div></div></article>`}
function moneyPage(snapshot:OpportunitySnapshot,archive=false){const path=archive?`/ai-money/${snapshot.date}/`:"/ai-money/",platforms=[...new Set(snapshot.moneyNews.flatMap(item=>item.sourcePlatforms))].join(" + "),archiveCta=archive?`<section class="method-strip"><b>这是 ${snapshot.date} 的归档</b><p>资讯列表已更新，请前往最新页面查看当前线索。</p><a href="/ai-money/" data-track="archive-money-current">查看最新创收资讯 →</a></section>`:"";return layout(`${snapshot.date} 使用 AI 工具挣钱的 50 条资讯`,`每日融合 Hacker News、DEV Community、Bing News、TechCrunch 与 VentureBeat 约 50 条 AI 商业化公开资讯。`,path,`<section class="page-head"><span class="kicker">AI BUSINESS SIGNALS · ${snapshot.date}</span><h1>使用 AI 工具挣钱<br>每日 50 条线索</h1><p>同时采集 Hacker News、DEV Community、Bing News、TechCrunch 与 VentureBeat，先在各站内部归一化，再按互动、时效和跨源覆盖生成本站排序。它们是待核实的商业化线索，不是收入证明或“保证赚钱”教程。</p><div class="freshness"><span><i class="live-dot"></i> 数据日期 ${snapshot.date}</span><span>${snapshot.moneyNews.length} 条</span><span>本榜来源：${esc(platforms)}</span></div></section>${archiveCta}${archive?"":moneyTop3Share}<section class="method-strip"><b>本站融合分</b><p>45% 站内热度 + 35% 发布时间 + 20% 跨源覆盖。不同平台先各自归一化，优先限制单一平台主导 22 条；候选不足 50 时再按融合分补齐。</p><a href="/methodology/">查看完整口径 →</a></section><section class="danger"><b>先核实，再行动</b><p>标题、产品自述和社区讨论都可能有偏差；不要因为单条资讯付费、投资或上传敏感数据。点击原文和每张卡片的来源证据交叉验证。</p></section>${archive?"":`<div class="directory opportunity-directory"><form class="filters" id="filters"><label class="search"><span>搜索线索</span><input name="q" type="search" placeholder="SaaS、客户、自动化、内容创作"></label>${select("signal","商业化信号",moneySignalOptions)}<button type="reset">清除筛选</button></form><section><div class="result-meta"><b><span id="result-count">${snapshot.moneyNews.length}</span> 条结果</b><span>多源候选每日融合重排</span></div><div id="empty" class="empty" hidden>没有匹配结果。</div><div class="opportunity-list">${snapshot.moneyNews.map(moneyNewsCard).join("")}</div></section></div><script type="module" src="${assetUrl("filter.js")}"></script>`}${archive?`<div class="opportunity-list">${snapshot.moneyNews.map(moneyNewsCard).join("")}</div>`:""}<section class="method-strip"><b>每天订阅新线索</b><p>RSS 每次更新包含当前约 50 条公开资讯和本站融合分。</p><a href="/ai-money.xml" data-track="rss-money">订阅 AI 创收资讯 RSS →</a></section>${shareBar("有人在找 AI 商业化案例？把可核对的原文线索发给他")}`)}
function skillsPage(snapshot:OpportunitySnapshot,archive=false){const path=archive?`/skills/${snapshot.date}/`:"/skills/",movement=!archive&&snapshot.date===opportunities.date?rankMovement(snapshot.skills,previousOpportunity?.skills):undefined,archiveCta=archive?`<section class="method-strip"><b>这是 ${snapshot.date} 的归档</b><p>Skill 融合榜已更新，请前往最新榜单。</p><a href="/skills/" data-track="archive-skills-current">查看最新 Skill Top 50 →</a></section>`:"";return layout(`${snapshot.date} 热度最高的 50 个 AI Agent Skill`,`融合 skills.sh 安装趋势与 GitHub 仓库关注、更新活跃信号的 Agent Skill Top 50。`,path,`<section class="page-head"><span class="kicker">AGENT SKILLS · FUSION TOP 50 · ${snapshot.date}</span><h1>热度最高的 50 个<br>AI Agent Skill</h1><p>本站把 skills.sh 的安装趋势与 GitHub 仓库 Star、Fork、最近提交融合排序，只保留可核对公开仓库的 Skill。热度不代表质量、安全、官方认可或适合你的项目。</p><div class="freshness"><span><i class="live-dot"></i> 数据日期 ${snapshot.date}</span><span>Top ${snapshot.skills.length}</span><span>来源：skills.sh + GitHub</span></div></section>${archiveCta}${archive?"":skillsTop3Share}<section class="method-strip"><b>本站融合分</b><p>60% 安装趋势 + 25% GitHub 仓库关注 + 15% 最近提交活跃度；同一个来源仓库最多占 5 席。</p><a href="/methodology/">查看完整口径 →</a></section><section class="danger"><b>安装前必须审查</b><p>Skill 会向 Agent 注入指令，部分还会调用脚本或外部服务。先阅读 SKILL.md、检查来源仓库和权限；榜单不构成安全背书。</p><a href="https://www.skills.sh/docs" target="_blank" rel="noopener noreferrer nofollow" data-track="skill-method">查看 skills.sh 排名说明 ↗</a></section>${archive?"":`<div class="directory opportunity-directory"><form class="filters" id="filters"><label class="search"><span>搜索 Skill 或来源</span><input name="q" type="search" placeholder="例如：browser、design、anthropics"></label><button type="reset">清除搜索</button></form><section><div class="result-meta"><b><span id="result-count">${snapshot.skills.length}</span> 个结果</b><span>${previousOpportunity?`与 ${previousOpportunity.date} 榜单比较`:"按本站多源融合分排序"}</span></div><div id="empty" class="empty" hidden>没有匹配结果。</div><div class="opportunity-list">${snapshot.skills.map((item,index)=>skillCard(item,index,movement)).join("")}</div></section></div><script type="module" src="${assetUrl("filter.js")}"></script>`}${archive?`<div class="opportunity-list">${snapshot.skills.map((item,index)=>skillCard(item,index)).join("")}</div>`:""}<section class="method-strip"><b>每天订阅 Skill Top 50</b><p>RSS 每次更新包含本站融合排名、安装趋势和 GitHub 仓库信号。</p><a href="/skills.xml" data-track="rss-skills">订阅 Skill 热榜 RSS →</a></section>${shareBar("发现值得研究的 Agent Skill？先把来源页保存下来")}`)}
const moneyNewsPage=withItemListSchema(moneyPage(opportunities),`${opportunities.date} AI 工具创收资讯`,"约 50 条多源融合的 AI 商业化公开线索。","/ai-money/",opportunities.generatedAt,opportunities.moneyNews.map(item=>({name:item.title,url:item.url})));
const trendingSkillsPage=withItemListSchema(skillsPage(opportunities),`${opportunities.date} Agent Skill Top 50`,"融合 skills.sh 安装趋势与 GitHub 仓库信号的 Agent Skill 榜单。","/skills/",opportunities.generatedAt,opportunities.skills.map(item=>({name:item.name,url:item.url})));

function stockProjectCard(item:StockProject,index:number){return `<article class="stock-project-card card" data-search="${esc(`${item.name} ${item.kind} ${item.category} ${item.summary}`.toLowerCase())}" data-kind="${esc(item.kind)}"><span class="opportunity-rank">${String(index+1).padStart(2,"0")}</span><div><div class="card-head"><span class="eyebrow">${esc(item.kind)} · ${esc(item.category)}</span><span class="pill">综合 ${item.score}</span></div><h2>${ext(item.url,item.name,"","stock-project")}</h2><p>${esc(item.summary)}</p><div class="fusion-scores"><b>${compactNumber(item.stars)} Star</b><span>${compactNumber(item.forks)} Fork</span><span>关注 ${item.popularityScore}</span><span>活跃 ${item.freshnessScore}</span></div><div class="card-actions">${ext(item.sourceUrl,"核对 GitHub 来源","","stock-source")}${saveButton(`stock-project:${item.id}`,item.name,item.url,`${item.kind} · AI 炒股情报`)}</div></div></article>`}
function stockNewsCard(item:StockNews,index:number){return `<article class="stock-news-card card" data-search="${esc(`${item.title} ${item.source} ${item.sourcePlatforms.join(" ")} ${item.signal}`.toLowerCase())}" data-kind="新闻" data-signal="${esc(item.signal)}"><span class="opportunity-rank">${String(index+1).padStart(2,"0")}</span><div><div class="card-head"><span class="eyebrow">${esc(item.signal)} · ${esc(item.source)}</span><time datetime="${item.publishedAt}">${zhDate(item.publishedAt)}</time></div><h2>${ext(item.url,item.title,"","stock-news")}</h2><div class="fusion-scores"><b>情报分 ${item.score}</b><span>来源 ${item.sourceScore}</span><span>时效 ${item.freshnessScore}</span></div><div class="card-actions">${item.evidence.map(source=>ext(source.url,source.platform,"","stock-news-source")).join("")}${saveButton(`stock-news:${item.id}`,item.title,item.url,`${item.signal} · AI 炒股新闻`)}</div></div></article>`}
function stocksPage(snapshot:StockSnapshot,archive=false){const path=archive?`/ai-stocks/${snapshot.date}/`:"/ai-stocks/",platforms=[...new Set(snapshot.news.flatMap(item=>item.sourcePlatforms))].join(" + "),archiveCta=archive?`<section class="method-strip"><b>这是 ${snapshot.date} 的归档</b><p>工具、项目和新闻已经更新，请前往当天最新情报。</p><a href="/ai-stocks/" data-track="archive-stocks-current">查看最新 AI 炒股情报 →</a></section>`:"",lists=`<section class="ranking-section"><div class="section-title"><div><span class="kicker">TOOLS & OPEN SOURCE · 12</span><h2>AI 股票工具与开源项目</h2></div><span>按 GitHub 关注度与最近提交活跃度排序</span></div><div class="opportunity-list">${snapshot.projects.map(stockProjectCard).join("")}</div></section><section class="ranking-section"><div class="section-title"><div><span class="kicker">NEWS · 12</span><h2>AI 炒股相关新闻</h2></div><span>本榜来源：${esc(platforms)}</span></div><div class="opportunity-list">${snapshot.news.map(stockNewsCard).join("")}</div></section>`;return layout(`${snapshot.date} AI 炒股工具、项目与新闻`,`每天更新 12 个 AI 股票研究工具和开源项目，以及 12 条多源相关新闻；只提供公开资料和风险提示。`,path,`<section class="page-head"><span class="kicker">AI STOCK INTELLIGENCE · ${snapshot.date}</span><h1>AI 炒股工具、项目<br>与每日新闻</h1><p>每天整理 12 个可核对 GitHub 来源的工具与开源项目，以及 12 条 AI 股票研究、量化交易、投资 Agent 和监管风险新闻。本站不预测涨跌、不荐股、不代客交易。</p><div class="freshness"><span><i class="live-dot"></i> 数据日期 ${snapshot.date}</span><span>共 ${snapshot.projects.length+snapshot.news.length} 条</span><span>${snapshot.projects.length} 项目 + ${snapshot.news.length} 新闻</span></div></section>${archiveCta}${archive?"":stocksTop3Share}<section class="danger"><b>AI 结论不能直接当交易指令</b><p>模型可能使用过时、错误或缺失数据；回测成绩不等于实盘收益，自动交易还涉及券商权限、API Key、滑点和风控。警惕“保证收益”和冒充 AI 的投资骗局。</p><a href="https://www.finra.org/investors/insights/artificial-intelligence-and-investment-fraud" target="_blank" rel="noopener noreferrer nofollow" data-track="stock-risk">查看 FINRA / SEC 投资者风险提示 ↗</a></section><section class="method-strip"><b>本站排序，不是收益排行</b><p>项目按 65% GitHub 关注度 + 35% 最近提交活跃度；新闻按 50% 来源内热度 + 40% 时效 + 10% 跨源覆盖。</p><a href="/methodology/">查看完整口径 →</a></section>${archive?lists:`<div class="directory opportunity-directory"><form class="filters" id="filters"><label class="search"><span>搜索全部 24 条</span><input name="q" type="search" placeholder="A股、量化、Agent、回测、风险"></label>${select("kind","内容类型",[["工具","工具"],["开源项目","开源项目"],["新闻","新闻"]])}${select("signal","新闻主题",[["工具 / 产品","工具 / 产品"],["市场 / 公司","市场 / 公司"],["研究 / 策略","研究 / 策略"],["监管 / 风险","监管 / 风险"]])}<button type="reset">清除筛选</button></form><section><div class="result-meta"><b><span id="result-count">${snapshot.projects.length+snapshot.news.length}</span> 条结果</b><span>每天更新并保留归档</span></div><div id="empty" class="empty" hidden>没有匹配结果。</div>${lists}</section></div><script type="module" src="${assetUrl("filter.js")}"></script>`}<section class="method-strip"><b>订阅每日 AI 炒股情报</b><p>RSS 包含当前 12 个项目和 12 条新闻，所有条目均可跳转公开来源。</p><a href="/ai-stocks.xml" data-track="rss-stocks">订阅 AI 炒股 RSS →</a></section>${!archive?`<section class="archive-block"><h2>每日归档</h2><p>保留最近 90 天工具、项目和新闻快照。</p><div>${stockHistory.map(item=>`<a href="/ai-stocks/${item.date}/">${item.date}</a>`).join("")}</div></section>`:""}${shareBar("有人在研究 AI 炒股工具？先把来源和风险一起发给他")}`)}
const aiStocksItems=[...stocks.projects.map(item=>({name:item.name,url:item.url})),...stocks.news.map(item=>({name:item.title,url:item.url}))];
const aiStocksPage=withItemListSchema(stocksPage(stocks),`${stocks.date} AI 炒股工具、项目与新闻`,"12 个 AI 股票研究工具或项目和 12 条多源相关新闻。","/ai-stocks/",stocks.generatedAt,aiStocksItems);

function weeklyItemCard(item:WeeklyDigestItem,index:number,section:string){return `<article class="stock-news-card card"><span class="opportunity-rank">${String(index+1).padStart(2,"0")}</span><div><div class="card-head"><span class="eyebrow">${esc(item.sourceLabels.join(" + "))}</span><span class="pill">周分 ${item.weeklyScore}</span></div><h2>${ext(item.url,item.title,"","weekly-item")}</h2><p>${esc(item.summary)}</p><div class="fusion-scores"><b>上榜 ${item.appearances} 天</b><span>最佳 #${item.bestRank}</span></div>${saveButton(`weekly:${section}:${item.id}`,item.title,item.url,`${section} · ${weekly.week} 周报`)}</div></article>`}
function weeklySection(title:string,kicker:string,items:WeeklyDigestItem[],section:string){return `<section class="ranking-section"><div class="section-title"><div><span class="kicker">${esc(kicker)} · TOP ${items.length}</span><h2>${esc(title)}</h2></div><span>按周内上榜持续性与日榜名次聚合</span></div><div class="opportunity-list">${items.map((item,index)=>weeklyItemCard(item,index,section)).join("")}</div></section>`}
function weeklyChangeCard(item:WeeklyChangeItem,index:number,kind:"persistent"|"newcomers"|"risers"){const signal=kind==="persistent"?`连续 ${item.appearances} 天上榜`:kind==="newcomers"?`最新快照首次出现 · #${item.latestRank}`:`#${item.previousRank} → #${item.latestRank} · ↑ ${item.rankDelta}`;return `<article class="stock-news-card card"><span class="opportunity-rank">${String(index+1).padStart(2,"0")}</span><div><div class="card-head"><span class="eyebrow">${esc(item.section)} · ${esc(item.sourceLabels.join(" + "))}</span><span class="pill">${esc(signal)}</span></div><h3>${ext(item.url,item.title,"","weekly-change")}</h3><p>${esc(item.summary)}</p></div></article>`}
function weeklyChangeSection(title:string,description:string,items:WeeklyChangeItem[],kind:"persistent"|"newcomers"|"risers"){return `<section class="ranking-section"><div class="section-title"><div><h2>${esc(title)}</h2><p>${esc(description)}</p></div><span>${items.length} 条可验证变化</span></div>${items.length?`<div class="opportunity-list">${items.map((item,index)=>weeklyChangeCard(item,index,kind)).join("")}</div>`:`<p class="note">当前有效快照中还没有满足条件的条目。</p>`}</section>`}
function weeklyChanges(digest:WeeklyDigest){const changes=digest.changes;return `<section class="guide-results"><div class="section-title"><div><span class="kicker">WEEKLY MOVEMENT</span><h2>本周变化雷达</h2></div><span>只比较至少 2 天的同类快照</span></div><p>参与判断：${esc(changes.eligibleGroups.join("、")||"暂无")}。暂不判断：${esc(changes.skippedGroups.join("、")||"无")}。</p></section>${weeklyChangeSection("连续上榜","至少在两个已采集日期进入同类日榜。",changes.persistent,"persistent")}${weeklyChangeSection("最新快照首次出现","只表示此前已采集日期未出现，不等于项目或新闻首次发布。",changes.newcomers,"newcomers")}${weeklyChangeSection("排名升温","比较最近两个已采集日期的同类榜单名次。",changes.risers,"risers")}`}
function topicSummary(digest:WeeklyDigest){return `<section class="guide-results"><div class="section-title"><div><span class="kicker">CROSS-LIST TOPICS</span><h2>跨榜主题追踪</h2></div><a href="/topics/" data-track="weekly-topics">查看主题中心 →</a></div><div class="category-grid">${digest.topics.map(topic=>`<a href="/topics/#${topic.id}" data-track="weekly-topic"><b>${esc(topic.label)}</b><span>${topic.itemCount} 条 · ${topic.sectionLabels.length} 个栏目 →</span></a>`).join("")}</div></section>`}
function weeklyPage(digest:WeeklyDigest,archive=false){const path=archive?`/weekly/${digest.week}/`:"/weekly/",archiveCta=archive?`<section class="method-strip"><b>这是 ${esc(digest.week)} 的归档</b><p>周报会随每日快照继续更新，请前往当前周报。</p><a href="/weekly/" data-track="archive-weekly-current">查看本周 AI 情报 →</a></section>`:"",sections=weeklySection("AI 热门新闻","NEWS",digest.headlines,"热门新闻")+weeklySection("热门开源项目","PROJECTS",digest.projects,"热门项目")+weeklySection("趋势模型","MODELS",digest.models,"趋势模型")+weeklySection("AI 创收线索","AI BUSINESS",digest.moneyNews,"AI 创收")+weeklySection("Agent Skill","SKILLS",digest.skills,"Agent Skill")+weeklySection("AI 股票工具与项目","AI STOCK PROJECTS",digest.stockProjects,"AI 炒股项目")+weeklySection("AI 炒股相关新闻","AI STOCK NEWS",digest.stockNews,"AI 炒股新闻");return layout(`${digest.week} AI 情报周报`,`汇总本周 AI 新闻、开源项目、趋势模型、创收线索、Agent Skill 和 AI 股票情报，并展示可验证的连续上榜、新出现与排名升温。`,path,`<section class="page-head"><span class="kicker">WEEKLY AI DIGEST · ${esc(digest.week)}</span><h1>一周 AI 情报<br>一次看完</h1><p>把每日热点、AI 创收、Agent Skill 与 AI 股票情报压缩成一份周报。只根据已保存的日榜快照聚合，不补写未采集日期，不生成投资或收入结论。</p><div class="freshness"><span><i class="live-dot"></i> ${digest.periodStart} 至 ${digest.periodEnd}</span><span>日榜 ${digest.snapshotDays.daily} 天</span><span>机会榜 ${digest.snapshotDays.opportunities} 天</span><span>AI 炒股 ${digest.snapshotDays.stocks} 天</span></div></section>${archiveCta}<section class="method-strip"><b>周分口径</b><p>70% 日榜名次强度 + 30% 已采集日期中的上榜覆盖率；页面同时显示上榜天数和最佳名次。覆盖不足 7 天时如实显示，不推断趋势。</p><a href="/methodology/">查看数据与排序边界 →</a></section>${weeklyChanges(digest)}${topicSummary(digest)}${sections}<section class="method-strip"><b>每周订阅</b><p>RSS 只推送周报归档入口，适合不想每天查看榜单的用户。</p><a href="/weekly.xml" data-track="rss-weekly">订阅 AI 情报周报 →</a></section>${!archive?`<section class="archive-block"><h2>周报归档</h2><p>每周快照持续保留，方便回看当周公开信号。</p><div>${weeklyHistory.map(item=>`<a href="/weekly/${item.week}/">${item.week}</a>`).join("")}</div></section>`:""}${shareBar("不想每天刷榜？把这份 AI 周报存下来")}`)}
const weeklyItems=[weekly.headlines,weekly.projects,weekly.models,weekly.moneyNews,weekly.skills,weekly.stockProjects,weekly.stockNews].flat().map(item=>({name:item.title,url:item.url}));
const currentWeeklyPage=withItemListSchema(weeklyPage(weekly),`${weekly.week} AI 情报周报`,"汇总本周反复上榜的 AI 新闻、项目、模型、创收、Skill 与股票情报。","/weekly/",weekly.generatedAt,weeklyItems);

function topicItemCard(item:WeeklyTopic["items"][number],index:number,topic:string){return `<article class="stock-news-card card"><span class="opportunity-rank">${String(index+1).padStart(2,"0")}</span><div><div class="card-head"><span class="eyebrow">${esc(item.section)} · ${esc(item.sourceLabels.join(" + "))}</span><span class="pill">周分 ${item.weeklyScore}</span></div><h3>${ext(item.url,item.title,"","topic-item")}</h3><p>${esc(item.summary)}</p><div class="fusion-scores"><b>上榜 ${item.appearances} 天</b><span>最佳 #${item.bestRank}</span></div>${saveButton(`topic:${topic}:${item.id}`,item.title,item.url,`${topic} · 跨榜主题`)}</div></article>`}
function topicSection(topic:WeeklyTopic){return `<section class="ranking-section" id="${topic.id}"><div class="section-title"><div><span class="kicker">${esc(topic.id)} · ${topic.itemCount} SIGNALS</span><h2>${esc(topic.label)}</h2><p>${esc(topic.description)}</p></div><span>${esc(topic.sectionLabels.join(" + "))}</span></div><div class="fusion-scores"><b>${topic.itemCount} 条匹配</b><span>${topic.sectionLabels.length} 个栏目</span><span>${topic.sourceLabels.length} 类来源</span></div><div class="card-actions"><button class="button topic-follow" type="button" data-topic-follow="${topic.id}" aria-pressed="false">关注主题</button><a class="button" href="/topics/${topic.id}.xml" data-track="rss-topic">订阅 ${esc(topic.label)} RSS →</a></div><div class="opportunity-list">${topic.items.map((item,index)=>topicItemCard(item,index,topic.label)).join("")}</div></section>`}
const topicsPage=withItemListSchema(layout(`${weekly.week} AI 主题追踪`,`从本周 AI 新闻、项目、模型、创收、Skill 与 AI 股票情报中生成达到跨栏目阈值的主题。`,"/topics/",`<section class="page-head"><span class="kicker">AI TOPIC TRACKER · ${weekly.week}</span><h1>跨榜追踪<br>本周 AI 主题</h1><p>同一个主题必须至少匹配 3 条内容并覆盖 2 个栏目才会展示。本站只聚合周报已有条目和公开来源，不自动扩写摘要，不批量生成薄内容页。</p><div class="freshness"><span><i class="live-dot"></i> ${weekly.periodStart} 至 ${weekly.periodEnd}</span><span>${weekly.topics.length} 个有效主题</span><span>${weekly.topics.reduce((sum,topic)=>sum+topic.itemCount,0)} 条主题匹配</span></div><div class="actions"><a class="button primary" href="/following/" data-track="following-open">查看我的关注 →</a></div></section><section class="method-strip"><b>主题不是标签堆砌</b><p>固定关键词规则先匹配，再要求跨栏目覆盖；单一榜单里的热点不会单独生成主题。一个条目可以同时属于多个真实相关主题。</p><a href="/methodology/">查看主题生成门槛 →</a></section><div class="category-grid">${weekly.topics.map(topic=>`<a href="#${topic.id}"><b>${esc(topic.label)}</b><span>${topic.itemCount} 条 · ${topic.sectionLabels.length} 栏目 ↓</span></a>`).join("")}</div>${weekly.topics.map(topicSection).join("")}<section class="method-strip"><b>订阅跨榜主题</b><p>主题 RSS 每周更新，条目仍直接链接原始公开来源。关注状态只保存在当前浏览器。</p><a href="/topics.xml" data-track="rss-topics">订阅全部主题 RSS →</a></section>${shareBar("发现值得持续观察的 AI 主题？把来源列表存下来")}`),`${weekly.week} AI 主题追踪`,"至少匹配 3 条周报内容并覆盖 2 个栏目的跨榜 AI 主题。","/topics/",weekly.generatedAt,weekly.topics.map(topic=>({name:topic.label,url:`${base}/topics/#${topic.id}`})));
function followingTopicCard(topic:WeeklyTopic){return `<article class="card" data-following-topic="${topic.id}" hidden><span class="eyebrow">${esc(topic.sectionLabels.join(" + "))}</span><h2><a href="/topics/#${topic.id}">${esc(topic.label)}</a></h2><p>${esc(topic.description)}</p><div class="fusion-scores"><b>${topic.itemCount} 条</b><span>${topic.sectionLabels.length} 个栏目</span></div><div class="card-actions"><a class="button primary" href="/topics/#${topic.id}" data-track="following-topic-open">查看最新内容</a><a class="button" href="/topics/${topic.id}.xml" data-track="rss-topic">主题 RSS</a><button class="button" type="button" data-topic-follow="${topic.id}" aria-pressed="true">已关注</button></div></article>`}
