const freeApiGuide=layout("2026 免费 AI API 怎么选：额度、类型与入口","按免费方式、模型类型和平台说明免费 AI API 的选择方法，并列出可核对来源的入口。","/guides/free-ai-api/",`<section class="page-head prose-head"><span class="kicker">FREE AI API GUIDE</span><h1>免费 AI API<br>不是一种免费</h1><p>周期额度、注册赠金、共享路由和开放权重经常被混在一起。先分清免费方式，再决定能否用于你的项目。</p></section><article class="prose"><h2>先看四种“免费”</h2><div class="comparison"><div><b>周期免费额度</b><p>按天或按月重置，适合原型、小流量应用和学习。</p></div><div><b>注册赠金</b><p>通常额度很小，用完即止，适合验证接口。</p></div><div><b>免费共享路由</b><p>模型和容量可能变化，不适合依赖固定输出的生产任务。</p></div><div><b>开放权重</b><p>下载免费不等于算力免费，需要自己承担机器和运维成本。</p></div></div><h2>平台额度速查</h2><p><a href="/guides/free-llm-api-providers/">先对比 ${providers.length} 个免费 LLM API 平台的额度类型和官方入口 →</a> · <a href="/guides/free-ai-api-no-topup/">只看不充值也能开始的 4 个官方入口 →</a></p><ul><li><a href="/guides/openrouter-free-models/">OpenRouter 免费模型</a>：查看 25+ 免费模型、<code>:free</code> 变体和每天 50 次基础限额。</li><li><a href="/guides/cloudflare-workers-ai-free-tier/">Cloudflare Workers AI</a>：查看每天 10,000 Neurons 的重置时间和超额行为。</li></ul><h2>按任务选择</h2><p>聊天与代码生成优先看上下文、速率和协议；图像、视频任务更应该关注单次消耗；Embedding 和 Rerank 则要看批量限制、向量维度与中文效果。不要只比较“模型名字”。</p><h2>上线前核对</h2><ol><li>免费额度是否写在官方定价或文档里。</li><li>是否需要绑卡，超额后会停用还是自动计费。</li><li>输入内容是否可能被用于改进产品。</li><li>地区、并发、RPM、TPM 和每日调用数是否满足需求。</li></ol><p><a href="/models/">浏览全部 ${models.length} 个免费模型入口 →</a></p></article><section class="guide-results"><div class="section-title"><span class="kicker">VERIFIED ENTRIES</span><h2>先从这些在线入口开始</h2></div><div class="cards standalone">${freeApiModels.map(modelCard).join("")}</div></section>${shareBar("需要免费 API 的朋友，先把这份核对清单发给他")}${articleSchema("2026 免费 AI API 怎么选：额度、类型与入口","/guides/free-ai-api/")}`);

const retrievalGuide=layout("免费 Embedding 与 Rerank 模型：RAG 选型入口","免费 Embedding、Rerank 模型与 API 入口，解释它们在 RAG 中的分工和选择方法。","/guides/free-embedding-rerank/",`<section class="page-head prose-head"><span class="kicker">RAG MODEL GUIDE</span><h1>Embedding 与 Rerank<br>到底怎么选</h1><p>Embedding 负责大范围召回，Rerank 负责把候选结果重新排序。多数 RAG 系统不是二选一，而是前后配合。</p></section><article class="prose"><h2>最小可用链路</h2><ol><li>用 Embedding 把文档转成向量并写入向量库。</li><li>查询时召回相似度最高的一批候选文档。</li><li>用 Rerank 对问题和候选文档逐条打分。</li><li>把排序靠前的内容交给生成模型回答。</li></ol><h2>免费方案怎么选</h2><p>小型中文知识库可以先用多语言 Embedding；当结果“相关但顺序不准”时再增加 Rerank。托管 API 省运维，本地开放权重更可控，但需要计算资源。</p><h2>别忽略这些字段</h2><p>向量维度、最大输入长度、批量大小、多语言能力、许可证和速率限制都会影响成本。模型榜单只提供入口，具体限制仍以来源页为准。</p></article><section class="guide-results"><div class="section-title"><span class="kicker">EMBEDDING + RERANK</span><h2>${retrievalModels.length} 个可核对入口</h2></div><div class="cards standalone">${retrievalModels.map(modelCard).join("")}</div></section>${shareBar("正在做 RAG？把这份选型入口收藏或分享")}${articleSchema("免费 Embedding 与 Rerank 模型：RAG 选型入口","/guides/free-embedding-rerank/")}`);

const visualGuide=layout("免费图像、视频与语义分割 AI 模型入口","免费图像生成、视频生成和语义分割模型入口，区分在线额度与开放权重。","/guides/free-image-video-models/",`<section class="page-head prose-head"><span class="kicker">VISUAL AI GUIDE</span><h1>图像、视频、分割<br>免费入口整理</h1><p>视觉模型的单次推理成本差异很大。“能免费试一次”和“能长期免费调用”完全不是一回事。</p></section><article class="prose"><h2>三类任务的差别</h2><p><b>图像生成</b>把文字或参考图变成图片；<b>视频生成</b>通常消耗更多算力；<b>语义分割</b>输出像素级区域，适合抠图、质检和场景理解。</p><h2>在线额度还是本地权重</h2><p>在线额度适合快速验证，开放权重适合对隐私和稳定性要求更高的任务。下载权重前要同时检查许可证、显存要求和模型卡限制。</p><h2>避免额度误判</h2><p>部分平台按计算单元扣费，而不是按“调用一次”计费。高分辨率或长视频可能迅速耗尽小额免费额度。</p></article><section class="guide-results"><div class="section-title"><span class="kicker">VISUAL MODELS</span><h2>${visualModels.length} 个图像与视频入口</h2></div><div class="cards standalone">${visualModels.map(modelCard).join("")}</div></section>${shareBar("做视觉 AI 的朋友可能正需要这些入口")}${articleSchema("免费图像、视频与语义分割 AI 模型入口","/guides/free-image-video-models/")}`);
const visualGuideWithVideo=visualGuide.replace("</article>",`<h2>3 个免费视频生成入口怎么选</h2><div class="comparison"><div><b>Wan 2.2 TI2V 5B</b><p>同时覆盖文生视频和图生视频。符合条件的托管路由可消耗 Hugging Face 月度免费额度，但视频推理通常很快耗尽小额额度。</p><p><a href="/models/wan22-video/">查看模型与来源 →</a></p></div><div><b>HunyuanVideo</b><p>当前目录记录为文生视频入口。在线可用 Provider、排队和免费额度会变化，调用前要回到模型页确认。</p><p><a href="/models/hunyuan-video/">查看模型与来源 →</a></p></div><div><b>LTX-Video</b><p>权重可下载，适合需要本地可控方案的用户；开放权重不代表显卡、部署或云端 API 免费。</p><p><a href="/models/ltx-video/">查看模型与来源 →</a></p></div></div><h2>免费试用前先确认</h2><ol><li>模型页当前是否显示可用的托管 Provider。</li><li>免费额度是月度赠金、活动额度还是仅开放权重。</li><li>所需分辨率、帧数和时长会消耗多少推理资源。</li><li>重要工作要保留本地运行或其他 Provider 的备选方案。</li></ol><p>资料审阅：2026-07-29。本站不上传素材、不代调用模型，也不承诺免费路由长期存在。</p></article>`);
const visualGuideUpdated=visualGuideWithVideo.replace(`"dateModified":"${reviewedAt}"`,`"dateModified":"2026-07-29"`);

const embeddingApiGuide=layout("2026 免费 Embedding API：中文向量模型与额度对比","对比 Gemini Embedding 2、Cloudflare BGE-M3、Qwen3 Embedding 与 Hugging Face 免费 Embedding API 的额度、模型和数据边界。","/guides/free-embedding-api/",`<section class="page-head prose-head"><span class="kicker">FREE EMBEDDING API · 2026</span><h1>免费 Embedding API<br>先看 3 个官方入口</h1><p>面向中文语义搜索与 RAG，优先比较免费层是否持续、批量限制、向量维度和数据使用方式，而不是只看模型名称。</p></section><article class="prose"><h2>3 个入口怎么选</h2><div class="comparison"><div><b>Gemini Embedding 2</b><p>Google 官方价格页当前把文本、图片、音频和视频输入列为 Free Tier 免费；免费层内容可能用于改进产品。</p><p><a href="/models/gemini-embedding/">查看模型入口 →</a></p></div><div><b>Cloudflare Workers AI</b><p>BGE-M3 与 Qwen3 Embedding 0.6B 当前均按每百万输入 Token 1,075 Neurons 计量，共享每天 10,000 Neurons 免费额度。</p><p><a href="/providers/cloudflare/">查看 Workers AI 入口 →</a></p></div><div><b>Hugging Face</b><p>Free 用户当前每月获得 0.10 美元 Inference Providers 额度，可用于符合条件的 Feature Extraction 路由；额度和可用 Provider 会变化。</p><p><a href="/providers/huggingface/">查看 HF 入口 →</a></p></div></div><h2>Cloudflare 免费额度能处理多少</h2><p>按官方当前单价，如果 10,000 Neurons 全部只用于 BGE-M3 或 Qwen3 Embedding 0.6B，理论上约对应 930 万输入 Token。这个数字是按价格表计算的上限，不是吞吐承诺；同一账户的其他 Workers AI 调用会共同消耗额度。</p><h2>中文 RAG 的最低检查项</h2><ol><li>查询和文档是否使用同一模型、同一归一化方式。</li><li>模型是否明确支持中文或多语言，最大输入长度是否覆盖文档切片。</li><li>向量维度是否能被现有向量库接受，切换模型后是否需要重建索引。</li><li>免费层输入是否可能被用于改进产品，敏感资料不要直接进入不合适的免费通道。</li></ol><h2>官方来源</h2><div class="comparison"><div><b>Gemini API 价格</b><p>${ext("https://ai.google.dev/gemini-api/docs/pricing","核对免费层与数据使用","","guide-source")}</p></div><div><b>Workers AI 价格</b><p>${ext("https://developers.cloudflare.com/workers-ai/platform/pricing/","核对 Neurons 单价","","guide-source")}</p></div><div><b>Hugging Face 额度</b><p>${ext("https://huggingface.co/docs/inference-providers/en/pricing","核对每月免费额度","","guide-source")}</p></div><div><b>HF Feature Extraction</b><p>${ext("https://huggingface.co/docs/inference-providers/tasks/feature-extraction","查看 API 说明","","guide-source")}</p></div></div><p>资料审阅：2026-07-26。限额、地区和模型路由可能调整，使用前请重新打开来源页。</p></article><section class="guide-results"><div class="section-title"><span class="kicker">EMBEDDING MODELS</span><h2>${models.filter(x=>x.category==="embedding").length} 个已收录向量模型</h2></div><div class="cards standalone">${models.filter(x=>x.category==="embedding").map(modelCard).join("")}</div></section>${shareBar("正在做中文 RAG？把这份免费 Embedding API 对比发给他")}${articleSchema("2026 免费 Embedding API：中文向量模型与额度对比","/guides/free-embedding-api/")}`);

const rerankApiGuide=layout("2026 免费 Rerank API 对比：Cohere 与 Cloudflare","免费 Rerank API 额度对比，整理 Cohere Trial Key 和 Cloudflare BGE Reranker 的免费限额、适用场景与官方入口。","/guides/free-rerank-api/",`<section class="page-head prose-head"><span class="kicker">FREE RERANK API · 2026</span><h1>免费 Rerank API<br>两个官方入口怎么选</h1><p>Rerank 用在向量召回之后，把候选文档按问题相关度重新排序。这里不做性能排名，只比较可核对的免费方式和调用边界。</p></section><article class="prose"><h2>结论先说</h2><div class="comparison"><div><b>Cloudflare BGE Reranker</b><p>Workers AI Free 计划每天共享 10,000 Neurons；BGE Reranker Base 当前按每百万输入 Token 283 Neurons 计量，适合已有 Cloudflare 账户的低成本 RAG 原型。</p><p><a href="/models/bge-reranker/">查看本站模型入口 →</a></p></div><div><b>Cohere Rerank</b><p>Cohere Evaluation Key 免费但受限：官方当前列出 Rerank 10 请求/分钟，Trial Key 每月最多 1,000 次 API 调用，适合小规模验证。</p><p><a href="/models/cohere-rerank-v4/">查看本站模型入口 →</a></p></div></div><h2>Cloudflare 免费额度怎么理解</h2><p>如果每天 10,000 Neurons 全部只用于 BGE Reranker Base，按 283 Neurons/百万输入 Token 计算，理论上约对应 3,530 万输入 Token。它只是按价格表计算的额度上限，不代表并发、吞吐或服务等级；同一账户的其他 Workers AI 调用会共同消耗免费额度，超额后 Free 计划请求会失败。</p><h2>什么时候需要 Rerank</h2><ol><li>向量检索能找到相关文档，但最相关结果经常排不进前几名。</li><li>知识库问题较短，候选文档较长，仅靠向量相似度容易偏题。</li><li>准备减少送入生成模型的文档数量，先用重排压缩上下文。</li></ol><p>如果连召回都不稳定，应先检查切片、Embedding 和查询改写，而不是直接增加 Rerank。可先阅读 <a href="/guides/free-embedding-rerank/">Embedding 与 Rerank 的最小 RAG 链路</a>。</p><h2>上线前检查</h2><ul><li>按“查询 + 候选文档”的总输入量估算额度，不要只数 API 请求。</li><li>确认单次候选数量、最大输入长度、批量限制与超时策略。</li><li>敏感文档进入托管 API 前，先核对平台的数据使用和保留条款。</li><li>免费层适合原型和低流量任务，不应当作固定 SLA。</li></ul><h2>官方来源</h2><div class="comparison"><div><b>Cloudflare Workers AI 价格</b><p>${ext("https://developers.cloudflare.com/workers-ai/platform/pricing/","核对每日额度与 Neurons 单价","","guide-source")}</p></div><div><b>BGE Reranker 模型文档</b><p>${ext("https://developers.cloudflare.com/workers-ai/models/bge-reranker-base/","查看请求参数与返回格式","","guide-source")}</p></div><div><b>Cohere Trial Key 限额</b><p>${ext("https://docs.cohere.com/docs/rate-limits","核对每分钟与每月限制","","guide-source")}</p></div><div><b>Embedding API 对比</b><p><a href="/guides/free-embedding-api/">先选召回模型 →</a></p></div></div><p>资料审阅：2026-07-27。价格、免费额度和速率限制可能调整，使用前请重新打开官方来源。</p></article><section class="guide-results"><div class="section-title"><span class="kicker">RERANK MODELS</span><h2>${models.filter(x=>x.category==="rerank").length} 个已收录重排模型</h2></div><div class="cards standalone">${models.filter(x=>x.category==="rerank").map(modelCard).join("")}</div></section>${shareBar("正在做 RAG？把这份免费 Rerank API 对比发给他")}${jsonLd({"@context":"https://schema.org","@type":"Article",headline:"2026 免费 Rerank API 对比：Cohere 与 Cloudflare",url:`${base}/guides/free-rerank-api/`,dateModified:"2026-07-27",inLanguage:"zh-CN",author:{"@type":"Organization",name:"免费 AI 目录"}})}`);

const imageApiGuide=layout("2026 免费图像生成 API：FLUX、Qwen Image 额度与入口","免费图像生成 API 对比，整理 Cloudflare Workers AI 的 FLUX 免费额度和 Hugging Face Qwen Image 月度赠金额度。","/guides/free-image-generation-api/",`<section class="page-head prose-head"><span class="kicker">FREE IMAGE GENERATION API · 2026</span><h1>免费图像生成 API<br>先算清每张图的消耗</h1><p>“有免费额度”不等于每天能生成固定张数。分辨率、步数、输入图片和具体模型都会改变消耗。</p></section><article class="prose"><h2>两个可核对入口</h2><div class="comparison"><div><b>Cloudflare Workers AI</b><p>Free 计划每天共享 10,000 Neurons。当前目录包含 FLUX.1 Schnell 与 FLUX.2 Klein 4B 等图像模型，超过免费额度后 Free 计划请求会失败。</p><p><a href="/providers/cloudflare/">查看平台与模型 →</a></p></div><div><b>Hugging Face Inference Providers</b><p>Free 用户当前每月有 0.10 美元推理额度，可尝试符合条件的 Text-to-Image 路由；实际可用 Provider、价格和模型状态以模型页为准。</p><p><a href="/models/qwen-image/">查看 Qwen Image 入口 →</a></p></div></div><h2>为什么不能写“每天免费多少张”</h2><p>Cloudflare 当前把 FLUX.1 Schnell 分成每个 512×512 tile 和每一步的 Neurons 消耗；FLUX.2 系列又区分输入、输出 tile 或百万像素。相同提示词改变分辨率或步数后，单张成本就会变化。本站因此只列官方单位，不制造一个脱离参数的固定张数。</p><h2>适合与不适合</h2><ul><li>适合验证提示词、生成产品占位图、个人 Demo 和低频内容制作。</li><li>不适合把免费层当成稳定批量出图服务，也不适合依赖长期固定模型与容量。</li><li>含人物、商标或受版权保护素材时，还要另外核对平台条款和使用权。</li></ul><h2>官方来源</h2><div class="comparison"><div><b>Workers AI 图像计价</b><p>${ext("https://developers.cloudflare.com/workers-ai/platform/pricing/","查看图像模型 Neurons","","guide-source")}</p></div><div><b>FLUX.1 Schnell 模型</b><p>${ext("https://developers.cloudflare.com/workers-ai/models/flux-1-schnell/","查看模型入口","","guide-source")}</p></div><div><b>Hugging Face 免费额度</b><p>${ext("https://huggingface.co/docs/inference-providers/en/pricing","查看月度额度","","guide-source")}</p></div><div><b>Text-to-Image API</b><p>${ext("https://huggingface.co/docs/inference-providers/tasks/text-to-image","查看任务文档","","guide-source")}</p></div></div><p>资料审阅：2026-07-26。图像模型价格和免费路由变化较快，调用前请核对实时页面。</p></article><section class="guide-results"><div class="section-title"><span class="kicker">IMAGE MODELS</span><h2>${models.filter(x=>x.category==="image_generation").length} 个已收录图像模型</h2></div><div class="cards standalone">${models.filter(x=>x.category==="image_generation").map(modelCard).join("")}</div></section>${shareBar("有人在找免费图像生成 API？把官方额度入口发给他")}${articleSchema("2026 免费图像生成 API：FLUX、Qwen Image 额度与入口","/guides/free-image-generation-api/")}`);

