const sitemapPageWithOpportunities=sitemapPage.replace("<section class=\"method-strip\"><b>机器可读入口</b>",`${sitemapGroup("情报与机会榜",[["AI 情报周报","/weekly/"],["跨榜 AI 主题追踪","/topics/"],["AI 工具创收资讯融合榜 50 条","/ai-money/"],["Agent Skill 融合榜 Top 50","/skills/"],["AI 炒股工具、项目与新闻","/ai-stocks/"]])}<section class="method-strip"><b>机器可读入口</b>`).replace("<a href=\"/feed.xml\">每日热点 RSS →</a>","<a href=\"/feed.xml\">每日热点 RSS →</a> · <a href=\"/weekly.xml\">AI 周报 RSS →</a> · <a href=\"/topics.xml\">主题追踪 RSS →</a> · <a href=\"/ai-stocks.xml\">AI 炒股 RSS →</a>");

const methodologyWithDailyDirectory=methodology
  .replace("至少要有官方定价页、官方文档、官方模型目录或可下载的开放权重页面。我们区分周期免费额度、小额额度、免费共享路由和本地开放权重；不会把“免费注册”写成“免费调用”。","人工收录的基础目录至少要有官方定价页、官方文档、官方模型目录或可下载的开放权重页面。每日任务还会从 OpenRouter 官方目录同步模型 ID 以 :free 结尾且输入、输出单价均为 0 的条目。我们区分周期免费额度、小额额度、免费共享路由和本地开放权重；不会把“免费注册”写成“免费调用”。")
  .replace("使用中英文关键词全网搜索，再核对站点首页、文档、价格页、条款与隐私页面。证据分为“有站方文档”“仅官网自述”“第三方线索”。这些等级描述资料完整度，不代表服务质量。","人工基础目录来自中英文全网搜索，并核对站点首页、文档、价格页、条款与隐私页面。每日任务会用 GitHub 公开仓库搜索发现候选，只有仓库描述和站点自身页面都出现客户端、协议与服务信息时才加入“第三方线索”；导航页、自托管工具和切换器会被排除。证据等级只描述资料完整度，不代表服务质量。")
